import java.util.*

fun solver(n: Int, m: Int): Int {
    var first = 0
    var second = 0
    var copyN = n
    val point = if (m % 2 == 0) m else m + 1
    val target = point / 2

    while (copyN != target) {
        if (copyN > target) {
            first += copyN - target
            copyN = target
        }
        if (copyN < target) {
            copyN *= 2
            first += 1
        }
    }
    first += if (m % 2 == 0) 1 else 2

    copyN = n
    while (copyN != m) {
        if (copyN < m) {
            copyN *= 2
        } else {
            second += copyN - m
            break
        }
        second += 1
    }

    return minOf(first, second)
}

fun main() {
    val scanner = Scanner(System.`in`)
    if (!scanner.hasNext()) return
    val n = scanner.nextInt()
    val m = scanner.nextInt()

    if (n > m) {
        println(n - m)
        return
    }

    var current = mutableSetOf(n)
    var steps = 0

    while (true) {
        val next = mutableSetOf<Int>()
        for (x in current) {
            val dec = x - 1
            if (dec >= 1) {
                if (dec == m) {
                    println(steps + 1)
                    return
                }
                next.add(dec)
            }
            val mul = x * 2
            if (mul <= m * 1.5) {
                if (mul == m) {
                    println(steps + 1)
                    return
                }
                next.add(mul)
            }
        }
        current = next
        steps++
    }
}

